UPDATE recipe SET recipe_image_source = IF(recipe_image_source IS NULL AND recipe_image_url IS NULL AND recipe_thumbnail_url IS NULL, 'hellofresh', recipe_image_source), recipe_image_url = IF(recipe_image_source = 'hellofresh' AND recipe_image_url IS NULL, 'https://img.example.test/full-0001.jpg', recipe_image_url), recipe_thumbnail_url = IF(recipe_image_source = 'hellofresh' AND recipe_thumbnail_url IS NULL, 'https://img.example.test/thumb/full-0001.jpg', recipe_thumbnail_url), recipe_description = COALESCE(recipe_description, 'Ein erfundener Text mit ''Anführungszeichen'' und \\ Backslash.'), recipe_cuisine = COALESCE(recipe_cuisine, 'Schwedisch'), recipe_rating_avg = COALESCE(recipe_rating_avg, 4.33), recipe_rating_count = COALESCE(recipe_rating_count, 120), recipe_published_date = COALESCE(recipe_published_date, '2024-03-05') WHERE recipe_id = 1 AND (recipe_description IS NULL OR recipe_image_url IS NULL OR recipe_thumbnail_url IS NULL OR recipe_image_source IS NULL OR recipe_cuisine IS NULL OR recipe_rating_avg IS NULL OR recipe_rating_count IS NULL OR recipe_published_date IS NULL);
UPDATE recipe SET recipe_image_source = IF(recipe_image_source IS NULL AND recipe_image_url IS NULL AND recipe_thumbnail_url IS NULL, 'hellofresh', recipe_image_source), recipe_image_url = IF(recipe_image_source = 'hellofresh' AND recipe_image_url IS NULL, 'https://img.example.test/sparse-0002.jpg', recipe_image_url) WHERE recipe_id = 2 AND (recipe_image_url IS NULL OR recipe_image_source IS NULL);
UPDATE recipe SET recipe_description = COALESCE(recipe_description, 'Nur ein Satz.') WHERE recipe_id = 3 AND (recipe_description IS NULL);
UPDATE recipe SET recipe_cuisine = COALESCE(recipe_cuisine, 'Amerikanisch'), recipe_rating_avg = COALESCE(recipe_rating_avg, 5.00), recipe_rating_count = COALESCE(recipe_rating_count, 1), recipe_published_date = COALESCE(recipe_published_date, '2023-12-31') WHERE recipe_id = 4 AND (recipe_cuisine IS NULL OR recipe_rating_avg IS NULL OR recipe_rating_count IS NULL OR recipe_published_date IS NULL);
